mapper.select:
SELECT o.id, o.order_no, o.category_id, o.fabric_name, o.plan_quantity, o.actual_quantity, o.unit, o.priority, o.status, o.current_process, o.process_index, o.plan_start_date, o.plan_end_date, o.actual_start_date, o.actual_end_date, o.timeout, o.operator_id, o.remark, o.create_time, p.id AS process_id, p.process_name, p.process_index, p.status AS process_status, p.start_time, p.end_time, p.output_quantity, p.defective_quantity, p.equipment FROM production_order o LEFT JOIN production_process p ON o.id = p.order_id
o.deleted = 0
AND o.id = #{id}
AND o.status = #{status}
ORDER BY o.priority DESC, o.create_time DESC, p.process_index ASC

SELECT status, COUNT(*) AS order_count, SUM(plan_quantity) AS total_plan_quantity, SUM(actual_quantity) AS total_actual_quantity FROM production_order WHERE deleted = 0
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY status ORDER BY status

SELECT o.id, o.order_no, o.fabric_name, o.plan_quantity, o.actual_quantity, o.unit, o.status, o.actual_start_date, o.actual_end_date, TIMESTAMPDIFF(HOUR, o.actual_start_date, o.actual_end_date) AS production_hours, CASE WHEN TIMESTAMPDIFF(HOUR, o.actual_start_date, o.actual_end_date) > 0 THEN o.actual_quantity / TIMESTAMPDIFF(HOUR, o.actual_start_date, o.actual_end_date) ELSE 0 END AS efficiency, fc.name AS category_name, su.real_name AS operator_name FROM production_order o LEFT JOIN fabric_category fc ON o.category_id = fc.id LEFT JOIN sys_user su ON o.operator_id = su.id WHERE o.deleted = 0 AND o.status = 'COMPLETED'
AND o.actual_end_date >= #{startDate}
AND o.actual_end_date <= #{endDate}
ORDER BY o.actual_end_date DESC

SELECT o.id, o.order_no, o.fabric_name, p.process_name, p.output_quantity, p.defective_quantity, CASE WHEN p.output_quantity > 0 THEN ROUND(p.defective_quantity * 100 / p.output_quantity, 2) ELSE 0 END AS defective_rate, p.end_time AS process_end_time FROM production_process p INNER JOIN production_order o ON p.order_id = o.id WHERE p.deleted = 0 AND o.deleted = 0 AND p.defective_quantity > 0
AND p.end_time >= #{startDate}
AND p.end_time <= #{endDate}
ORDER BY defective_rate DESC
